5	// Raíz del repositorio y carpeta de datos, localizadas subiendo desde el directorio de trabajo.
6	static string? Subir(Func<string, bool> ok)
7	{
8	    for (var d = new DirectoryInfo(Directory.GetCurrentDirectory()); d != null; d = d.Parent)
9	        if (ok(d.FullName)) return d.FullName;
10	    return null;
11	}
12	
13	var dataDir = Environment.GetEnvironmentVariable("EVALS_DATA");
14	var raiz = Subir(d => File.Exists(Path.Combine(d, "TutorFlow.sln")));
15	if (string.IsNullOrEmpty(dataDir))
16	{
17	    var padre = Subir(d => Directory.Exists(Path.Combine(d, "data", "reglamento")));
18	    dataDir = padre is null ? null : Path.Combine(padre, "data");
19	}
20	if (dataDir is null || !Directory.Exists(dataDir))
21	{
22	    Console.Error.WriteLine("No se encontró la carpeta de datos (use EVALS_DATA).");
23	    return 2;
24	}
25	var evalsDir = raiz is null ? Path.Combine(Directory.GetCurrentDirectory(), "evals") : Path.Combine(raiz, "evals");
26	
27	var url = (Environment.GetEnvironmentVariable("EVALS_API_URL") is { Length: > 0 } u ? u : "http://localhost:8080").TrimEnd('/');
28	var pausaMs = int.TryParse(Environment.GetEnvironmentVariable("EVALS_PAUSA_MS"), out var pm) ? pm : 1500;
29	var esperaMs = int.TryParse(Environment.GetEnvironmentVariable("EVALS_ESPERA_MS"), out var em) ? em : 2000;
30	const int Reintentos = 3;
31	var rutaAud = Environment.GetEnvironmentVariable("EVALS_AUDITORIA") is { Length: > 0 } ea
32	    ? Path.GetFullPath(ea)
33	    : Path.Combine(raiz ?? Directory.GetCurrentDirectory(), "logs", "auditoria.jsonl");
34	var llave = Environment.GetEnvironmentVariable("LLM_API_KEY"); // solo para R2; no se envía a ningún lado
35	
36	if (string.IsNullOrEmpty(llave))
37	    Console.WriteLine("ADVERTENCIA: LLM_API_KEY no está definida en el entorno del runner; la regla de no filtrar la llave no se puede comprobar.");
38	
39	var casos = new List<Caso>();
40	void CargarCasos(string ruta)
41	{
42	    var lista = JsonSerializer.Deserialize<List<Caso>>(File.ReadAllText(ruta), Evaluador.JsonOpts);
43	    if (lista != null) casos.AddRange(lista);
44	}
45	Corpus corpus;
46	try
47	{
48	    CargarCasos(Path.Combine(dataDir, "preguntas-ejemplo.json"));
49	    var extra = Path.Combine(evalsDir, "casos-adicionales.json");
50	    if (File.Exists(extra)) CargarCasos(extra);
51	    corpus = Corpus.Cargar(dataDir);
52	}
53	catch (Exception ex) when (ex is JsonException or InvalidDataException or IOException)
54	{
55	    Console.Error.WriteLine("Entrada de evals inválida: " + ex.Message);
56	    return 2;
57	}
58	using var http = new HttpClient { Timeout = TimeSpan.FromSeconds(120) };
59	var resultados = new List<ResultadoCaso>();
60	
61	Console.WriteLine($"Evals contra {url}: {casos.Count} casos");
62	for (var i = 0; i < casos.Count; i++)
63	{
64	    var caso = casos[i];
65	    if (i > 0 && pausaMs > 0) await Task.Delay(pausaMs);
66	    var cuerpoPeticion = JsonSerializer.Serialize(new
67	    {
68	        pregunta = caso.Pregunta,
69	        usuario = new { rol = caso.Usuario.Rol, id = caso.Usuario.Id },
70	    });
71	    var desdeAud = UsoModelo.Longitud(rutaAud);
72	    RespuestaHttp? resp = null;
73	    var motivoFinal = "";
74	    for (var intento = 0; intento <= Reintentos; intento++)
75	    {
76	        if (intento > 0) await Task.Delay(esperaMs * (1 << (intento - 1)));
77	        try
78	        {
79	            using var content = new StringContent(cuerpoPeticion, Encoding.UTF8, "application/json");
80	            using var hr = await http.PostAsync(url + "/api/asistente/preguntar", content);
81	            var texto = await hr.Content.ReadAsStringAsync();
82	            var codigo = (int)hr.StatusCode;
83	            if (codigo is 503 or 429) { motivoFinal = $"proveedor sin respuesta ({codigo})"; continue; }
84	            resp = new RespuestaHttp(codigo, texto);
85	            break;
86	        }
87	        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
88	        {
89	            motivoFinal = "error de red: " + ex.GetType().Name;
90	        }
91	    }
92	    var res = resp is null ? Evaluador.SinResultado(caso, motivoFinal) : Evaluador.Evaluar(caso, resp, corpus, llave);
93	    UsoModelo.Aplicar(res, UsoModelo.Buscar(rutaAud, desdeAud, caso.Pregunta, caso.Usuario.Id));
94	    resultados.Add(res);
95	    var estado = res.Estado switch { Estado.Ok => "OK", Estado.Falla => "FALLA", _ => "SIN RESULTADO" };
96	    Console.WriteLine($"{res.Id,-8} {res.Escenario,-10} {estado,-13} {string.Join("; ", res.Motivos)}");
97	    var modeloTxt = res.AuditoriaEncontrada
98	        ? $"  modelo pedido={res.ModeloPedido ?? "-"} respondido=[{string.Join(", ", res.ModelosRespondidos)}] http={res.Codigo?.ToString() ?? "-"} entrada={res.TokensEntrada} salida={res.TokensSalida} tokens={res.TokensUso} costo={res.CostoUsoUsd:F6}"
99	        : $"  modelo=desconocido http={res.Codigo?.ToString() ?? "-"} tokens={res.TokensUso} costo={res.CostoUsoUsd:F6} (ADVERTENCIA: sin línea de auditoría en {rutaAud})";
100	    Console.WriteLine(modeloTxt + (res.ModeloDistinto ? "  MODELO DISTINTO" : ""));
101	}
102	
103	var resumen = Evaluador.Resumir(resultados);
104	var veredicto = resumen.CodigoSalida switch { 0 => "APROBADA", 1 => "REPROBADA", _ => "INCONCLUSA" };
105	Console.WriteLine();
106	Console.WriteLine($"Aprobadas: {resumen.Aprobadas}/{resumen.ConResultado} con resultado ({resumen.Total} casos, {resumen.SinResultado} sin resultado)");
107	Console.WriteLine($"Puntaje: {resumen.Puntaje:P1} (umbral {resumen.Umbral:P0})");
