92	    public static Corpus Cargar(string dataDir)
93	    {
94	        var c = new Corpus();
95	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "reglamento"), "*.md"))
96	        {
97	            var doc = Path.GetFileName(f);
98	            foreach (var l in File.ReadLines(f))
99	            {
100	                if (l.StartsWith("## ", StringComparison.Ordinal))
101	                    c.Citas.Add((doc, l[3..].Trim()));
102	            }
103	        }
104	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "api"), "*.json"))
105	        {
106	            using var d = JsonDocument.Parse(File.ReadAllText(f));
107	            if (d.RootElement.ValueKind != JsonValueKind.Array) continue;
108	            var delArchivo = new List<(Persona P, bool ConSemestre)>();
109	            foreach (var e in d.RootElement.EnumerateArray())
110	            {
111	                if (e.ValueKind != JsonValueKind.Object) continue;
112	                if (!e.TryGetProperty("id", out var id) || !e.TryGetProperty("nombre", out var nom)
113	                    || !e.TryGetProperty("programa", out var prog)) continue;
114	                var p = new Persona(id.GetString() ?? "", nom.GetString() ?? "", prog.GetString() ?? "");
115	                // Los estudiantes se distinguen de los coordinadores por tener semestre.
116	                delArchivo.Add((p, e.TryGetProperty("semestre", out _)));
117	            }
118	            // Falla cerrada (igual que RN-14 en Datos.cs): la forma es una decisión por archivo.
119	            if (delArchivo.Count > 0 && delArchivo.Any(x => x.ConSemestre != delArchivo[0].ConSemestre))
120	                throw new InvalidDataException($"El archivo '{Path.GetFileName(f)}' mezcla usuarios con y sin 'semestre'; no se puede clasificar estudiantes y coordinadores.");
121	            foreach (var (p, conSemestre) in delArchivo)
122	                (conSemestre ? c.Estudiantes : c.Coordinadores).Add(p);
123	        }
124	        var repetidos = c.Estudiantes.Select(x => x.Id).Intersect(c.Coordinadores.Select(x => x.Id)).ToList();
125	        if (repetidos.Count > 0)
126	            throw new InvalidDataException($"Ids presentes como estudiante y coordinador: {string.Join(", ", repetidos)}.");
127	        if (c.Estudiantes.Count == 0 || c.Coordinadores.Count == 0)
128	            throw new InvalidDataException("No se encontraron estudiantes y coordinadores en los datos; la regla R2 no se puede comprobar.");
129	        return c;
130	    }
131	
132	    /// <summary>Estudiantes que el usuario NO puede ver.</summary>
133	    public IEnumerable<Persona> Prohibidos(UsuarioCaso u)
134	    {
135	        if (u.Rol == "estudiante") return Estudiantes.Where(e => e.Id != u.Id);
136	        if (u.Rol == "coordinador")
137	        {
138	            var prog = Coordinadores.FirstOrDefault(x => x.Id == u.Id)?.Programa;
139	            return Estudiantes.Where(e => e.Programa != prog);
140	        }
141	        return Estudiantes;
142	    }
143	}
