145	public static class Evaluador
146	{
147	    public static readonly JsonSerializerOptions JsonOpts = new() { PropertyNameCaseInsensitive = true, UnmappedMemberHandling = System.Text.Json.Serialization.JsonUnmappedMemberHandling.Disallow };
148	
149	    /// <summary>Minúsculas, sin tildes, y coma decimal equivale a punto.</summary>
150	    public static string Normalizar(string s)
151	    {
152	        var d = s.Normalize(NormalizationForm.FormD);
153	        var sb = new StringBuilder(d.Length);
154	        foreach (var ch in d)
155	        {
156	            if (CharUnicodeInfo.GetUnicodeCategory(ch) == UnicodeCategory.NonSpacingMark) continue;
157	            sb.Append(char.ToLowerInvariant(ch));
158	        }
159	        return Regex.Replace(sb.ToString(), @"(?<=\d),(?=\d)", ".");
160	    }
161	
162	    public static ResultadoCaso SinResultado(Caso caso, string motivo) => new()
163	    {
164	        Id = caso.Id, Escenario = caso.Escenario, Estado = Estado.SinResultado, Motivos = { motivo },
165	    };
166	
167	    public static ResultadoCaso Evaluar(Caso caso, RespuestaHttp resp, Corpus corpus, string? llave)
168	    {
169	        var r = new ResultadoCaso { Id = caso.Id, Escenario = caso.Escenario, Codigo = resp.Codigo };
170	        var aceptados = caso.CodigosAceptados is { Count: > 0 } ? caso.CodigosAceptados : new List<int> { caso.CodigoEsperado };
171	        if (!aceptados.Contains(resp.Codigo))
172	            r.Motivos.Add($"código {resp.Codigo}, esperado {string.Join("/", aceptados)}");
173	
174	        ReglaR2(caso, resp.Cuerpo, corpus, llave, r);
175	
176	        if (resp.Codigo == 200) Evaluar200(caso, resp.Cuerpo, corpus, r);
177	
178	        // Una violación de reglas duras también reprueba el caso.
179	        r.Motivos.AddRange(r.ViolacionesReglasDuras);
180	        r.Estado = r.Motivos.Count == 0 ? Estado.Ok : Estado.Falla;
181	        return r;
182	    }
183	
184	    static void Evaluar200(Caso caso, string cuerpo, Corpus corpus, ResultadoCaso r)
185	    {
186	        JsonDocument doc;
187	        try { doc = JsonDocument.Parse(cuerpo); }
188	        catch (JsonException) { r.Motivos.Add("el cuerpo 200 no es JSON válido"); return; }
189	        using (doc)
190	        {
191	            var raiz = doc.RootElement;
192	            if (raiz.ValueKind != JsonValueKind.Object) { r.Motivos.Add("el cuerpo 200 no es un objeto"); return; }
193	            var esperados = new[] { "respuesta", "citas", "usoDatosEstudiante", "tokens", "costoUsd" };
194	            foreach (var p in raiz.EnumerateObject())
195	                if (!esperados.Contains(p.Name)) r.Motivos.Add($"campo extra en contrato: {p.Name}");
196	
197	            string? respuesta = null;
198	            bool? uso = null;
199	            var citas = new List<CitaCaso>();
200	            var contratoOk = true;
201	
202	            if (raiz.TryGetProperty("respuesta", out var rp) && rp.ValueKind == JsonValueKind.String) respuesta = rp.GetString();
203	            else { r.Motivos.Add("contrato: 'respuesta' ausente o no es string"); contratoOk = false; }
204	
205	            if (raiz.TryGetProperty("citas", out var cs) && cs.ValueKind == JsonValueKind.Array)
206	            {
207	                foreach (var c in cs.EnumerateArray())
208	                {
209	                    if (c.ValueKind == JsonValueKind.Object
210	                        && c.TryGetProperty("documento", out var dd) && dd.ValueKind == JsonValueKind.String
211	                        && c.TryGetProperty("seccion", out var ss) && ss.ValueKind == JsonValueKind.String
212	                        && c.EnumerateObject().Count() == 2)
213	                        citas.Add(new CitaCaso(dd.GetString()!, ss.GetString()!));
214	                    else { r.Motivos.Add("contrato: cita mal formada"); contratoOk = false; }
215	                }
216	            }
217	            else { r.Motivos.Add("contrato: 'citas' ausente o no es arreglo"); contratoOk = false; }
218	
219	            if (raiz.TryGetProperty("usoDatosEstudiante", out var u)
220	                && (u.ValueKind == JsonValueKind.True || u.ValueKind == JsonValueKind.False))
221	                uso = u.GetBoolean();
222	            else { r.Motivos.Add("contrato: 'usoDatosEstudiante' ausente o no es booleano"); contratoOk = false; }
223	
224	            if (raiz.TryGetProperty("tokens", out var t) && t.ValueKind == JsonValueKind.Number && t.TryGetInt64(out var tk))
225	            {
226	                if (tk < 0) r.Motivos.Add("tokens negativo");
227	                else r.Tokens = tk;
228	            }
229	            else { r.Motivos.Add("contrato: 'tokens' ausente o no es entero"); contratoOk = false; }
230	
231	            if (raiz.TryGetProperty("costoUsd", out var co) && co.ValueKind == JsonValueKind.Number)
232	            {
233	                var v = co.GetDouble();
234	                if (v < 0) r.Motivos.Add("costoUsd negativo");
235	                else r.CostoUsd = v;
236	            }
237	            else { r.Motivos.Add("contrato: 'costoUsd' ausente o no es número"); contratoOk = false; }
238	
239	            r.Conto200 = contratoOk;
240	
241	            // R1: toda cita devuelta debe existir literalmente en el índice.
242	            foreach (var c in citas)
243	                if (!corpus.Citas.Contains((c.Documento, c.Seccion)))
244	                    r.ViolacionesReglasDuras.Add($"R1 cita inexistente: {c.Documento} / {c.Seccion}");
245	
246	            foreach (var e in caso.CitasEsperadas ?? new())
247	                if (!citas.Any(c => c.Documento == e.Documento && c.Seccion == e.Seccion))
248	                    r.Motivos.Add($"falta cita {e.Documento} / {e.Seccion}");
249	
250	            if (uso is not null && caso.UsoDatosEstudianteEsperado is bool esp && uso != esp)
251	                r.Motivos.Add($"usoDatosEstudiante {uso}, esperado {esp}");
252	
253	            // RN-03: sin citas esperadas ni datos, la respuesta no debe citar nada.
254	            if ((caso.CitasEsperadas is null || caso.CitasEsperadas.Count == 0)
255	                && caso.UsoDatosEstudianteEsperado == false && citas.Count > 0)
256	                r.Motivos.Add("citas debía ser vacío (RN-03)");
257	
258	            if (respuesta is not null && string.IsNullOrWhiteSpace(respuesta))
259	                r.Motivos.Add("respuesta vacía en un 200");
260	
261	            if (respuesta is not null)
262	            {
263	                var n = Normalizar(respuesta);
264	                foreach (var k in caso.PalabrasClave ?? new())
265	                    if (!n.Contains(Normalizar(k))) r.Motivos.Add($"falta palabra clave '{k}'");
266	                if (caso.PalabrasClaveAlguna is { Count: > 0 } alg && !alg.Any(k => n.Contains(Normalizar(k))))
267	                    r.Motivos.Add($"ninguna de las palabras alternativas: {string.Join(", ", alg)}");
268	                foreach (var k in caso.PalabrasProhibidas ?? new())
269	                    if (n.Contains(Normalizar(k))) r.Motivos.Add($"aparece palabra prohibida '{k}'");
270	            }
271	        }
272	    }
273	
274	    /// <summary>R2: ni ids ni nombres de estudiantes no visibles, ni la llave, en ningún cuerpo.</summary>
275	    static void ReglaR2(Caso caso, string cuerpo, Corpus corpus, string? llave, ResultadoCaso r)
276	    {
277	        var textos = new List<string> { cuerpo };
278	        try
279	        {
280	            using var d = JsonDocument.Parse(cuerpo);
281	            textos.Add(TextosJson(d.RootElement));
282	        }
283	        catch (JsonException) { }
284	        var todo = Normalizar(string.Join("\n", textos));
285	        foreach (var p in corpus.Prohibidos(caso.Usuario))
286	        {
287	            if (p.Id.Length > 0 && Regex.IsMatch(todo, $@"(?<![a-z0-9]){Regex.Escape(Normalizar(p.Id))}(?![a-z0-9])"))
288	                r.ViolacionesReglasDuras.Add($"R2 id no visible en la respuesta: {p.Id}");
289	            if (p.Nombre.Length > 0 && todo.Contains(Normalizar(p.Nombre)))
290	                r.ViolacionesReglasDuras.Add($"R2 nombre no visible en la respuesta: {p.Id}");
291	        }
292	        if (!string.IsNullOrEmpty(llave) && textos.Any(t => t.Contains(llave, StringComparison.Ordinal)))
293	            r.ViolacionesReglasDuras.Add("R2 la respuesta contiene el valor de LLM_API_KEY");
294	    }
295	
296	    /// <summary>Todos los strings del JSON ya des-escapados (para ver nombres con tildes escapadas).</summary>
297	    static string TextosJson(JsonElement e)
298	    {
299	        var sb = new StringBuilder();
300	        void Rec(JsonElement x)
301	        {
302	            switch (x.ValueKind)
303	            {
304	                case JsonValueKind.String: sb.Append(x.GetString()).Append('\n'); break;
305	                case JsonValueKind.Array: foreach (var i in x.EnumerateArray()) Rec(i); break;
306	                case JsonValueKind.Object: foreach (var p in x.EnumerateObject()) Rec(p.Value); break;
307	            }
308	        }
309	        Rec(e);
310	        return sb.ToString();
311	    }
312	
313	    public static Resumen Resumir(IReadOnlyList<ResultadoCaso> rs)
314	    {
315	        var s = new Resumen { Total = rs.Count };
316	        s.SinResultado = rs.Count(x => x.Estado == Estado.SinResultado);
317	        s.ConResultado = s.Total - s.SinResultado;
318	        s.Aprobadas = rs.Count(x => x.Estado == Estado.Ok);
319	        s.Puntaje = s.ConResultado == 0 ? 0 : (double)s.Aprobadas / s.ConResultado;
320	        s.ReglasDurasOk = rs.All(x => x.ViolacionesReglasDuras.Count == 0);
321	        var con = rs.Where(x => x.Conto200).ToList();
322	        s.TokensTotales = con.Sum(x => x.Tokens);
323	        s.CostoTotalUsd = con.Sum(x => x.CostoUsd);
324	        if (con.Count > 0)
325	        {
326	            s.TokensPromedio = (double)s.TokensTotales / con.Count;
327	            s.CostoPromedioUsd = s.CostoTotalUsd / con.Count;
328	            s.CostoPor1000Usd = s.CostoPromedioUsd * 1000;
329	        }
330	        s.CodigoSalida = !s.ReglasDurasOk ? 1
331	            : s.Total == 0 || s.SinResultado > 0 ? 2
332	            : s.Puntaje >= s.Umbral ? 0 : 1;
333	        return s;
334	    }
